_choice_class() {
    cat <<-'EOF'
IN	Internet class
CH	Chaos class
CHAOS	Chaos class (alias for CH)
HS	Hesiod class
HESIOD	Hesiod class (alias for HS)
NONE	no class
ANY	any class
EOF
}

_choice_ednsopt() {
    [[ "${ARGC_CWORD:-}" != *:* ]] || return 0
    printf 'nsid\0\tName server identifier (3)\n'
    printf 'ecs\0\tClient subnet (8)\n'
    printf 'expire\0\tZone expire (9)\n'
    printf 'cookie\0\tDNS cookie (10)\n'
    printf 'keepalive\0\tTCP keepalive (11)\n'
    printf 'padding\0\tEDNS padding (12)\n'
    printf 'chain\0\tChain query (13)\n'
    printf 'ede\0\tExtended DNS error (15)\n'
    printf 'client-tag\0\tClient tag (16)\n'
    printf 'server-tag\0\tServer tag (17)\n'
    printf 'report-channel\0\tReport channel (18)\n'
    printf 'update-lease\0\tUpdate lease (19)\n'
}

_choice_opcode() {
    cat <<-'EOF'
QUERY	standard query (0)
IQUERY	inverse query (1)
STATUS	server status (2)
NOTIFY	zone change notification (4)
UPDATE	dynamic update (5)
EOF
}

_choice_server() {
    local word="${ARGC_CWORD:-}"
    if [[ -n "$word" && "$word" != @* ]]; then
        return 0
    fi
    printf '__argc_prefix=@\n'
    printf '__argc_filter=%s\n' "${word#@}"
    if [[ -r /etc/resolv.conf ]]; then
        gawk '$1 == "nameserver" { print $2 }' /etc/resolv.conf
    fi
    if [[ -r /etc/hosts ]]; then
        gawk '!/^[[:space:]]*#/ { sub(/#.*/, ""); for (i = 1; i <= NF; i++) print $i }' /etc/hosts
    fi
}

_choice_source_address() {
    if command -v ip >/dev/null 2>&1; then
        ip -o addr show 2>/dev/null | gawk '$3 == "inet" || ($3 == "inet6" && $4 !~ /^fe80:/) {
            split($4, a, "/")
            print a[1] "\t" $2
        }'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig 2>/dev/null | gawk '
            /^[^ \t]/ { iface = $1; sub(/:$/, "", iface) }
            $1 == "inet" { print $2 "\t" iface }
            $1 == "inet6" && $2 !~ /^fe80:/ { sub(/%.*$/, "", $2); print $2 "\t" iface }
        '
    fi
}

_choice_type() {
    cat <<-'EOF'
A	IPv4 address
AAAA	IPv6 address
AFSDB	AFS database location
ANY	any record type
APL	address prefix list
AXFR	full zone transfer
CAA	certification authority authorization
